const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open))});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));document.querySelectorAll('[data-service]').forEach(b=>b.addEventListener('click',()=>{document.querySelector('#service').value=b.dataset.service;document.querySelector('#plan').scrollIntoView({behavior:'smooth'});document.querySelector('#service').focus({preventScroll:true})}));document.querySelector('#year').textContent=new Date().getFullYear();document.querySelector('#date').min=new Date().toLocaleDateString('en-CA');let draft='';document.querySelector('#enquiry').addEventListener('submit',e=>{e.preventDefault();draft=`Joy Ripples enquiry draft\nName: ${document.querySelector('#name').value.trim()}\nService: ${document.querySelector('#service').value}\nDate: ${document.querySelector('#date').value}\nGuests: ${document.querySelector('#guests').value}\nDetails: ${document.querySelector('#details').value.trim()}`;const result=document.querySelector('#result');result.hidden=false;try{localStorage.setItem('joy-ripples-enquiry',draft);result.textContent='Draft saved on this device. It has not been sent to the hotel.\n\n'+draft}catch{result.textContent='Draft prepared below. Device storage is unavailable.\n\n'+draft}document.querySelector('#copy').hidden=false});document.querySelector('#copy').addEventListener('click',async e=>{try{await navigator.clipboard.writeText(draft);e.target.textContent='Enquiry copied'}catch{e.target.textContent='Select the draft text above to copy'}});
const photoDialog=document.querySelector('#photo-dialog');document.querySelectorAll('[data-image]').forEach(button=>button.addEventListener('click',()=>{document.querySelector('#dialog-image').src=button.dataset.image;document.querySelector('#dialog-image').alt=button.querySelector('img').alt;document.querySelector('#dialog-caption').textContent=button.dataset.caption;photoDialog.showModal()}));document.querySelector('.dialog-close').addEventListener('click',()=>photoDialog.close());photoDialog.addEventListener('click',e=>{if(e.target===photoDialog){const bounds=photoDialog.getBoundingClientRect();if(e.clientX<bounds.left||e.clientX>bounds.right||e.clientY<bounds.top||e.clientY>bounds.bottom)photoDialog.close()}});
// Reveal only when motion is permitted; content stays visible without JavaScript.
const motionPreference=window.matchMedia('(prefers-reduced-motion: reduce)');
let sectionObserver;
function setupReveals(){
 if(sectionObserver)sectionObserver.disconnect();
 document.querySelectorAll('.motion-pending').forEach(el=>el.classList.remove('motion-pending','motion-visible'));
 if(motionPreference.matches||!('IntersectionObserver' in window))return;
 sectionObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('motion-visible');sectionObserver.unobserve(entry.target)}}),{threshold:0.08});
 document.querySelectorAll('.intro-images,.intro-copy,.brand-story,.section-heading,.card,.gather-photo,.gather-content,.gallery-item,.plan>div,.plan form').forEach(el=>{if(el.getBoundingClientRect().top<window.innerHeight)return;el.classList.add('motion-pending');sectionObserver.observe(el)});
}
setupReveals();motionPreference.addEventListener('change',setupReveals);
document.querySelectorAll('[data-filter]').forEach(filter=>filter.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{const active=b===filter;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});document.querySelectorAll('.gallery-item').forEach(item=>{item.hidden=filter.dataset.filter!=='all'&&item.dataset.category!==filter.dataset.filter;item.classList.remove('motion-pending','motion-visible')})}));
